// The fixtures were generated by pnpm 12.22.0 with lockfile.format set to v13.
func TestParsePnpmLockV13(t *testing.T) {
	t.Run("reads resolved dependencies and integrity", func(t *testing.T) {
		packages, relationships := parsePnpmV13Fixture(t, "testdata/pnpm-v13/pnpm-lock.yaml")
		require.Len(t, packages, 2)
		byName := make(map[string]pkg.Package, len(packages))
		for _, p := range packages {
			byName[p.Name] = p
		}
		number := byName["is-number"]
		odd := byName["is-odd"]
		require.Equal(t, "pkg:npm/is-number@6.0.0", number.PURL)
		require.Equal(t, "pkg:npm/is-odd@3.0.1", odd.PURL)

		metadata, ok := number.Metadata.(pkg.PnpmLockEntry)
		require.True(t, ok)
		assert.Equal(t, "sha512-Wu1VHeILBK8KAWJUAiSZQX94GmOE45Rg6/538fKwiloUu21KncEkYGPqob2oSZ5mUT73vLGrHQjKw3KMPwfDzg==", metadata.Resolution.Integrity)
		assert.Contains(t, relationships, artifact.Relationship{
			From: number,
			To:   odd,
			Type: artifact.DependencyOfRelationship,
		})
	})

	t.Run("reads packages with resolved peer dependencies", func(t *testing.T) {
		packages, relationships := parsePnpmV13Fixture(t, "testdata/pnpm-v13-peers/pnpm-lock.yaml")
		byPURL := make(map[string]pkg.Package, len(packages))
		for _, p := range packages {
			byPURL[p.PURL] = p
		}
		assert.Len(t, byPURL, 5)
		for _, purl := range []string{
			"pkg:npm/js-tokens@4.0.0",
			"pkg:npm/loose-envify@1.4.0",
			"pkg:npm/react@18.2.0",
			"pkg:npm/react-dom@18.2.0",
			"pkg:npm/scheduler@0.23.2",
		} {
			assert.Contains(t, byPURL, purl)
		}
		assert.Contains(t, relationships, artifact.Relationship{
			From: byPURL["pkg:npm/react@18.2.0"],
			To:   byPURL["pkg:npm/react-dom@18.2.0"],
			Type: artifact.DependencyOfRelationship,
		})
	})
}

func TestParsePnpmLockV13SnapshotDependencies(t *testing.T) {
	const lockfile = `{
		"lockfileVersion": "13.0",
		"packages": {
			"example@1.0.0": {
				"dependencies": {"shared": "1.0.0"},
				"peerDependencies": {
					"unresolved": "^1.0.0",
					"transitive": {"version": "1.0.0", "below": true},
				},
				"snapshots": [
					{"dependencies": {"local": {"specifier": "file:local", "version": "file:local"}}},
					{"optionalDependencies": {"optional": "2.0.0"}},
				],
			},
		},
	}`
	packages, err := parsePnpmLockStream(file.NewLocationReadCloser(
		file.NewLocation("pnpm-lock.yaml"), io.NopCloser(strings.NewReader(lockfile)),
	))
	require.NoError(t, err)
	assert.Equal(t, map[string]string{
		"shared":   "1.0.0",
		"local":    "file:local",
		"optional": "2.0.0",
	}, packages["example@1.0.0"].Dependencies)
}

func parsePnpmV13Fixture(t *testing.T, fixture string) ([]pkg.Package, []artifact.Relationship) {
	t.Helper()
	reader, err := os.Open(fixture)
	require.NoError(t, err)
	t.Cleanup(func() { _ = reader.Close() })

	cataloger := newGenericPnpmLockAdapter(CatalogerConfig{IncludeDevDependencies: true})
	packages, relationships, err := cataloger.parsePnpmLock(t.Context(), nil, nil, file.NewLocationReadCloser(file.NewLocation(fixture), reader))
	require.NoError(t, err)
	return packages, relationships
}
